// State compatibility fixtures (docs/dev/02 F0-7, 06 §3).
//
// Tests/fixtures/state_0.0.1_<name>.bin are plugin states saved by the 0.0.1
// beta format (root GAPFILL_STATE, version 1): one per factory preset, three
// hand-edited sessions and corrupt variants. They are generated ONCE (before
// the Phase 0 refactor) and never regenerated by a feature PR; the writer below
// refuses to overwrite an existing file.

#include "../support/TestRig.h"

#include <iostream>

using namespace gapfill;
using namespace gftest;

namespace
{
    juce::String slug (const juce::String& name)
    {
        juce::String out;

        for (auto c : name.toLowerCase())
            out << (juce::CharacterFunctions::isLetterOrDigit (c) ? juce::String::charToString (c) : juce::String ("_"));

        return out;
    }

    juce::File fixtureFile (const juce::String& name)
    {
        return testDataDir().getChildFile ("fixtures").getChildFile ("state_0.0.1_" + name + ".bin");
    }

    juce::MemoryBlock readFixture (const juce::String& name)
    {
        juce::MemoryBlock block;
        const auto file = fixtureFile (name);
        GF_EXPECT_MSG (file.existsAsFile(), "missing fixture " + file.getFileName());
        file.loadFileAsData (block);
        GF_EXPECT_MSG (block.getSize() > 0, "empty fixture " + file.getFileName());
        return block;
    }

    void writeFixtureOnce (const juce::String& name, const juce::MemoryBlock& data)
    {
        const auto file = fixtureFile (name);

        if (file.existsAsFile())
            return;                       // fixtures are never regenerated

        file.getParentDirectory().createDirectory();
        GF_EXPECT_MSG (file.replaceWithData (data.getData(), data.getSize()), "could not write " + file.getFileName());
    }

    juce::MemoryBlock saveState (GapFillAudioProcessor& proc)
    {
        juce::MemoryBlock block;
        proc.getStateInformation (block);
        return block;
    }

    /** Real parameter value as the DSP reads it. */
    float rawValue (GapFillAudioProcessor& p, const juce::String& id)
    {
        return p.getValueTreeState().getRawParameterValue (id)->load();
    }

    void expectSameParameters (GapFillAudioProcessor& a, GapFillAudioProcessor& b, const juce::String& what)
    {
        for (const auto& id : allParameterIDs())
        {
            const auto va = rawValue (a, id), vb = rawValue (b, id);
            GF_EXPECT_MSG (std::abs (va - vb) <= 1.0e-4f * juce::jmax (1.0f, std::abs (va)),
                           what + ": parameter " + id + " is " + juce::String (va) + ", expected " + juce::String (vb));
        }
    }

    juce::StringArray fixtureNames()
    {
        juce::StringArray names;
        const auto& presets = getFactoryPresets();

        for (const auto& p : presets)
            names.add ("preset_" + slug (p.name));

        names.add ("session_extreme");
        names.add ("session_zero_weights");
        names.add ("session_midi_mappings");
        return names;
    }

    /** Builds the processor a fixture is supposed to restore to. */
    void configureExpected (GapFillAudioProcessor& p, const juce::String& name)
    {
        const auto& presets = getFactoryPresets();

        if (name.startsWith ("preset_"))
        {
            for (int i = 0; i < (int) presets.size(); ++i)
                if ("preset_" + slug (presets[(size_t) i].name) == name)
                    applyPreset (p.getValueTreeState(), i);

            return;
        }

        auto& state = p.getValueTreeState();

        if (name == "session_extreme")
        {
            int i = 0;

            for (const auto& id : allParameterIDs())
                state.getParameter (id)->setValueNotifyingHost ((i++ % 2) == 0 ? 0.0f : 1.0f);
        }
        else if (name == "session_zero_weights")
        {
            for (int i = 0; i < numAlgos; ++i)
                state.getParameter (algoWeightID ((Algo) i))->setValueNotifyingHost (0.0f);
        }
        else if (name == "session_midi_mappings")
        {
            applyPreset (state, 2);
            p.getMidiLearnManager().setMapping ("wet", 74);
            p.getMidiLearnManager().setMapping ("fill", 21);
            p.getMidiLearnManager().setMapping ("dry", 7);
        }
    }
}

//==============================================================================
GF_TEST (StateCompat, write_fixtures_when_requested)
{
    if (! writeGoldenMode())
        return;

    for (const auto& name : fixtureNames())
    {
        GapFillAudioProcessor p;
        configureExpected (p, name);
        writeFixtureOnce (name, saveState (p));
    }

    GapFillAudioProcessor init;
    const auto good = saveState (init);

    // Truncated: only the first third of a valid state.
    juce::MemoryBlock truncated (good.getData(), good.getSize() / 3);
    writeFixtureOnce ("corrupt_truncated", truncated);

    // Bit flips: a seeded sprinkling of damaged bytes in the middle.
    juce::MemoryBlock flipped (good);
    juce::Random rng (0x6f6c6421);

    for (int i = 0; i < 24; ++i)
        static_cast<std::uint8_t*> (flipped.getData())[(size_t) (flipped.getSize() / 4
                                  + (size_t) rng.nextInt ((int) (flipped.getSize() / 2)))] ^= (std::uint8_t) (1 << rng.nextInt (8));

    writeFixtureOnce ("corrupt_bitflips", flipped);
}

GF_TEST (StateCompat, every_factory_preset_fixture_restores_its_parameters)
{
    if (writeGoldenMode())
        return;

    for (const auto& name : fixtureNames())
    {
        GapFillAudioProcessor expected, loaded;
        prepareProcessor (loaded, 48000.0, 512, false);
        configureExpected (expected, name);

        const auto block = readFixture (name);
        loaded.setStateInformation (block.getData(), (int) block.getSize());
        expectSameParameters (loaded, expected, name);
    }
}

GF_TEST (StateCompat, midi_mapping_fixture_restores_cc_assignments)
{
    if (writeGoldenMode())
        return;

    GapFillAudioProcessor loaded;
    const auto block = readFixture ("session_midi_mappings");
    loaded.setStateInformation (block.getData(), (int) block.getSize());

    GF_EXPECT (loaded.getMidiLearnManager().getMappedCC ("wet") == 74);
    GF_EXPECT (loaded.getMidiLearnManager().getMappedCC ("fill") == 21);
    GF_EXPECT (loaded.getMidiLearnManager().getMappedCC ("dry") == 7);
}

GF_TEST (StateCompat, init_fixture_renders_scenario_A_golden)
{
    if (writeGoldenMode())
        return;

    GapFillAudioProcessor loaded;
    const auto block = readFixture ("preset_init");
    loaded.setStateInformation (block.getData(), (int) block.getSize());
    const auto result = renderGoldenScenarioA (loaded);

    const auto file = goldenPath ("A_drum_loop_default.f32");

    if (! file.existsAsFile())
    {
        std::cout << "         [golden] no baseline for platform '" << goldenPlatform() << "': UNVERIFIED" << std::endl;
        return;
    }

    juce::AudioBuffer<float> expected;
    GF_EXPECT (readGoldenFile (file, expected, result.out.getNumChannels(), result.out.getNumSamples()));
    const auto d = compareBuffers (result.out, expected, 1.0e-5);
    GF_EXPECT_MSG (d.firstBad < 0, "old 0.0.1 Init state no longer renders the golden (first bad sample "
                                     + juce::String (d.firstBad) + ")");
}

GF_TEST (StateCompat, restored_fixture_sounds_like_the_directly_configured_preset)
{
    if (writeGoldenMode())
        return;

    // Bit-identical: restoring the saved state must be indistinguishable from
    // setting the parameters directly.
    for (const char* name : { "preset_drum_gap_glitch", "preset_breakcore_destroyer", "session_extreme",
                              "session_zero_weights", "session_midi_mappings" })
    {
        GapFillAudioProcessor expected, loaded;
        configureExpected (expected, name);
        const auto block = readFixture (name);
        loaded.setStateInformation (block.getData(), (int) block.getSize());

        const auto a = renderGoldenScenarioA (expected);
        const auto b = renderGoldenScenarioA (loaded);
        const auto d = compareBuffers (a.out, b.out, 0.0);
        GF_EXPECT_MSG (d.firstBad < 0, juce::String (name) + ": fixture render differs from direct configuration at sample "
                                         + juce::String (d.firstBad));
        GF_EXPECT (a.fills == b.fills);
    }
}

GF_TEST (StateCompat, corrupt_fixtures_never_crash_and_never_leave_invalid_parameters)
{
    if (writeGoldenMode())
        return;

    for (const char* name : { "corrupt_truncated", "corrupt_bitflips" })
    {
        GapFillAudioProcessor p;
        prepareProcessor (p, 48000.0, 512, false);
        const auto block = readFixture (name);
        p.setStateInformation (block.getData(), (int) block.getSize());   // must not throw/crash

        for (const auto& id : allParameterIDs())
        {
            const auto v = rawValue (p, id);
            GF_EXPECT_MSG (std::isfinite (v), juce::String (name) + ": non-finite parameter " + id);
        }

        const auto out = renderGoldenScenarioA (p);
        GF_EXPECT (allFinite (out.out));
    }
}

GF_TEST (StateCompat, oversized_blob_is_rejected_without_changing_parameters)
{
    if (writeGoldenMode())
        return;

    GapFillAudioProcessor p;
    setParams (p, { { "wet", 33.0f } });

    juce::MemoryBlock junk;
    junk.setSize (4 * 1024 * 1024);
    junk.fillWith (0xA5);
    p.setStateInformation (junk.getData(), (int) junk.getSize());

    GF_EXPECT_NEAR (rawValue (p, "wet"), 33.0f, 1.0e-3);
}
